const fs = require('fs');
const input = fs.readFileSync(0, 'utf-8').trim();
const myarray = input.split(/\s+/)[0];
let cnt = 0;
const len = myarray.length;
for (let i = 0; i < len; i++) {
    if (myarray[i] === 'Q') {
        for (let j = i + 1; j < len; j++) {
            if (myarray[j] === 'A') {
                for (let l = j + 1; l < len; l++) {
                    if (myarray[l] === 'Q') {
                        cnt++;
                    }
                }
            }
        }
    }
}
console.log(cnt);

